#!/usr/bin/env bash
# 010 T025: verify-before-replace for regenerated byte-identity snapshots.
# Usage (repo root): bash specs/010-navigation-improvements/evidence/snapshot-diff.sh <old-dir> <new-dir>
# Compares every file present in BOTH dirs after stripping exactly the intended 010 changes:
#   - the ` tap` class on text links (K1/K2)
#   - the Pager's `here` slot and stack classes (K2)
#   - appended specimens, matched by their exact 010 labels (contracts/components.md Catalogue)
#   - the removed public-header nav `<nav class="nav" aria-label="Site">…</nav>` (FR-010), in
#     layout snapshots only (the SiteHeader catalogue page keeps its nav specimen)
#   - the three new catalogue index entries
# then collapses whitespace. Equal = keep the regenerated file; any residue = stop and escalate.
# Files only in one dir are listed (new slugs are expected to be new-only).
set -uo pipefail
OLD="$1"; NEW="$2"; fails=0

norm() { # norm <file> <relpath>
  perl -0777 -pe '
    my $rel = $ENV{REL};
    s/ class="text-link tap"/ class="text-link"/g;
    s/<div class="here"[^>]*>.*?<\/div>//gs;
    s/ class="pager(?: pager-stack(?: pager-stack-all)?)"/ class="pager"/g;
    my $labels = join "|", map quotemeta, (
      "With gallery link, middle photo", "With gallery link, first photo", "With gallery link, last photo",
      "One-photo gallery", "Long gallery title (stacks on small screens)",
      "Public site (brand only)", "Tap area");
    s/\s*<section class="specimen"[^>]*><h2 class="specimen-label"[^>]*>(?:$labels)<\/h2>.*?<\/section>(?=\s*(?:<section class="specimen"|<\/main>))//gs;
    if ($rel =~ /(public-layout|PublicLayoutPage)/) { s/\s*<nav class="nav" aria-label="Site"[^>]*>.*?<\/nav>//gs; }
    if ($rel =~ /(^|\/)index\.html$/) { s/<li[^>]*><a href="\/ui\/molecules\/(?:gallery-link|gallery-neighbours|membership-status)"[^>]*>[^<]*<\/a><\/li>//g; }
    s/\s+/ /g; s/> </></g;
  ' "$1"
}

while IFS= read -r rel; do
  if [ ! -f "$NEW/$rel" ]; then echo "ONLY-OLD $rel"; fails=$((fails+1)); continue; fi
  a=$(REL="$rel" norm "$OLD/$rel"); b=$(REL="$rel" norm "$NEW/$rel")
  if cmp -s "$OLD/$rel" "$NEW/$rel"; then echo "SAME     $rel"
  elif [ "$a" = "$b" ]; then echo "EQUAL    $rel (differs only by intended 010 changes)"
  else
    echo "RESIDUE  $rel"; fails=$((fails+1))
    diff <(echo "$a" | fold -w 160) <(echo "$b" | fold -w 160) | head -8
  fi
done < <(cd "$OLD" && find . -type f -name '*.html' | sed 's|^\./||' | LC_ALL=C sort)
(cd "$NEW" && find . -type f -name '*.html' | sed 's|^\./||' | LC_ALL=C sort) | while IFS= read -r rel; do
  [ -f "$OLD/$rel" ] || echo "NEW-ONLY $rel"
done
echo
[ "$fails" -eq 0 ] && echo "ALL EQUAL" || echo "$fails RESIDUE/MISSING"
exit "$fails"
